# What the wire carries (decisions/023), as the data dictionary's entries
# state it (meridian.bounds): a scale of 0 to DECIMAL_SCALE.most, and an
# integer whose magnitude is below 10 to the DECIMAL_DIGITS.
_TOO_MANY_DIGITS = 10**DECIMAL_DIGITS
_LOW_HALF = 2**64 - 1


@dataclass(frozen=True)
class Money:
    """An amount of currency: a Decimal (or an int) and the asset it is in.

    One value rather than an amount with its currency beside it, so a call
    carrying amounts in two currencies cannot pair either with the wrong one.
    From contract v18 a Money names its cash instrument: a fiat currency by
    its ISO 4217 code, Money("12.50", "USD"), which core resolves; an asset
    with no ISO 4217 code by `instrument_id` alone, as W3.1 resolved it.
    """

    amount: Decimal | int
    currency_code: str = ""
    instrument_id: str = ""


def _decimal(value: Decimal | int, name: str) -> ops.Decimal:
    """A number as the wire carries it: its integer, in two 64-bit halves, and
    the scale it was stated with. Exact, or refused naming the field; never
    rounded, and never normalised."""
    if isinstance(value, bool) or not isinstance(value, (Decimal, int)):
        raise TypeError(f"{name} is a Decimal or an int, not {type(value).__name__}")
    if isinstance(value, int):
        integer, scale = value, 0
    else:
        sign, digits, exponent = value.as_tuple()
        if not isinstance(exponent, int):
            raise ValueError(f"{name} is not a finite number")
        magnitude = int("".join(map(str, digits))) * 10 ** max(exponent, 0)
        integer, scale = -magnitude if sign else magnitude, max(-exponent, 0)
    if scale > DECIMAL_SCALE.most:
        raise ValueError(
            f"{name} has {scale} decimal places; at most {DECIMAL_SCALE.most} cross the wire, "
            "and it is refused rather than rounded"
        )
    if abs(integer) >= _TOO_MANY_DIGITS:
        raise ValueError(f"{name} has more than {DECIMAL_DIGITS} digits; it is refused rather than rounded")
    return ops.Decimal(high=integer >> 64, low=integer & _LOW_HALF, scale=scale)


def _money(value: Money, name: str) -> ops.Money:
    """An amount and its currency, the amount converted as any Decimal is."""
    if not isinstance(value, Money):
        raise TypeError(f"{name} is a meridian.Money, not {type(value).__name__}")
    if not isinstance(value.currency_code, str):
        raise TypeError(f"{name}'s currency_code is a str, not {type(value.currency_code).__name__}")
    if not isinstance(value.instrument_id, str):
        raise TypeError(f"{name}'s instrument_id is a str, not {type(value.instrument_id).__name__}")
    if not value.currency_code and not value.instrument_id:
        raise ValueError(f"{name} names no asset: a currency_code or an instrument_id")
    return ops.Money(
        amount=_decimal(value.amount, name),
        currency_code=value.currency_code,
        instrument_id=value.instrument_id,
    )


#: Each enum type's names, its short names and its values, read once: a row
#: converts several enums, and a stream sends thousands of rows a second.
_ENUMS: dict[Any, tuple[dict[str, int], dict[str, int], frozenset[int]]] = {}


def _enum_names(kind: Any) -> tuple[dict[str, int], dict[str, int], frozenset[int]]:
    """`kind`'s names (ASSET_CLASS_EQUITY), its names without the enum's
    prefix in lower case (equity) and its values, kept for the next call."""
    prefix = re.sub(r"(?<!^)(?=[A-Z])", "_", kind.DESCRIPTOR.name).upper() + "_"
    names = dict(kind.items())
    short = {n.removeprefix(prefix).lower(): v for n, v in names.items() if n.startswith(prefix)}
    held = _ENUMS[kind] = (names, short, frozenset(names.values()))
    return held


def _enum(kind: Any, value: Any, name: str) -> Any:
    """An enum value as the wire carries it: one `kind` defines, given as the
    value, its name (ASSET_CLASS_EQUITY) or its name without the enum's
    prefix in lower case (equity). None or an empty string is unset. Anything
    else is refused naming the field, never sent for the sidecar to refuse."""
    if value is None or value == "":
        return None
    names, short, values = _ENUMS.get(kind) or _enum_names(kind)
    if isinstance(value, str):
        if value in names:
            return names[value]
        if value in short:
            return short[value]
    elif isinstance(value, int) and not isinstance(value, bool) and value in values:
        return value
    raise ValueError(
        f"{name} is {value!r}, which {kind.DESCRIPTOR.name} does not define; "
        f"one of {', '.join(n for n in short if n != 'unspecified') or ', '.join(names)}"
    )


def _stated(**flags: bool | int | None) -> dict[str, Any]:
    """An optional flag or count as keyword arguments for the wire's message:
    absent when None, which is "not stated" and never False or 0 (contract v8,
    v18)."""
    return {name: value for name, value in flags.items() if value is not None}


def _arm(oneof: str, **arms: Any) -> dict[str, Any]:
    """The arm of a oneof that is set, as keyword arguments for the wire's
    message: none when none is, and refused naming the oneof when two are.
    Each arm is None when unset (contract v8)."""
    given = {name: value for name, value in arms.items() if value is not None}
    if len(given) > 1:
        raise ValueError(
            f"{oneof} takes one of {', '.join(arms)}; "
            f"{' and '.join(given)} were given"
        )
    return given


def _date(value: date | str, name: str) -> str:
    """A date as the wire carries it, its ISO 8601 text (2026-10-09), empty
    for none: given as a date, or as that text. Refused naming the field, a
    moment (a datetime) and text that is no date alike, never sent for the
    sidecar to refuse (contract v18)."""
    if isinstance(value, datetime):
        raise TypeError(f"{name} is a date, not a moment: {value.date().isoformat()}, not {value.isoformat()}")
    if isinstance(value, date):
        return value.isoformat()
    if not isinstance(value, str):
        raise TypeError(f"{name} is a date or its ISO 8601 text, not {type(value).__name__}")
    if value:
        try:
            stated = date.fromisoformat(value).isoformat()
        except ValueError:
            stated = ""
        if stated != value:
            raise ValueError(f"{name} is {value!r}, which is no date: YYYY-MM-DD, as 2026-10-09")
    return value


def _batch(rows: Sequence[Any], bound: Count, name: str) -> None:
    """A batch's rows within the data dictionary's bound, or refused naming
    the field before anything is sent (contract v18)."""
    if not bound.least <= len(rows) <= bound.most:
        raise ValueError(f"{name} holds {len(rows)} rows; a batch is {bound.least} to {bound.most}")


def as_decimal(message: ops.Decimal) -> Decimal:
    """A Decimal read back from the wire exactly as it was stated: 150 at scale
    2 is Decimal('1.50'). Built from its digits rather than by arithmetic,
    which would round at the context's precision."""
    integer = (message.high << 64) | message.low
    if message.scale > DECIMAL_SCALE.most or abs(integer) >= _TOO_MANY_DIGITS:
        raise ValueError(f"{integer} at scale {message.scale} is outside what the wire carries")
    digits = tuple(int(digit) for digit in str(abs(integer)))
    return Decimal((int(integer < 0), digits, -message.scale))


def as_money(message: ops.Money) -> Money:
    """A Money read back from the wire, its amount as as_decimal reads it."""
    return Money(as_decimal(message.amount), message.currency_code, message.instrument_id)


